#include "ay8910.h"
#include <string.h>
static const int16_t ayvol[16]={0,72,102,144,203,287,406,574,811,1146,1618,2286,3229,4560,6440,9100};
static uint16_t period12(zz_ay8910_t*a,unsigned c){uint16_t p=(uint16_t)a->reg[c*2]|((uint16_t)(a->reg[c*2+1]&15)<<8);return p?p:1;}
static void tone_inc(zz_ay8910_t*a,unsigned c){uint16_t p=period12(a,c);a->inc[c]=(uint32_t)(((uint64_t)a->clock<<32)/((uint64_t)16u*p*a->rate));}
static void noise_inc(zz_ay8910_t*a){uint32_t p=a->reg[6]&31u;if(!p)p=1;a->noise_inc=(uint32_t)(((uint64_t)a->clock<<32)/((uint64_t)16u*p*a->rate));}
static void env_inc(zz_ay8910_t*a){uint32_t p=(uint32_t)a->reg[11]|((uint32_t)a->reg[12]<<8);if(!p)p=1;a->env_inc=(uint32_t)(((uint64_t)a->clock<<32)/((uint64_t)256u*p*a->rate));}
static void env_shape(zz_ay8910_t*a,uint8_t s){a->env_continue=(s>>3)&1;a->env_attack=(s>>2)&1;a->env_alt=(s>>1)&1;a->env_hold=s&1;a->env_dir=a->env_attack?1:-1;a->env_step=a->env_attack?0:15;a->env_holding=0;a->env_phase=0;}
void zz_ay8910_reset(zz_ay8910_t*a,uint32_t clock,uint32_t rate){unsigned i;memset(a,0,sizeof(*a));a->clock=clock?clock:1789773u;a->rate=rate?rate:44100u;a->lfsr=0x1ffffu;for(i=0;i<3;i++)tone_inc(a,i);noise_inc(a);env_inc(a);env_shape(a,0);a->reg[7]=0x3f;a->stereo=0x3f;}
void zz_ay8910_stereo(zz_ay8910_t*a,uint8_t mask){a->stereo=mask&0x3fu;}
void zz_ay8910_write(zz_ay8910_t*a,uint8_t r,uint8_t d){r&=15;a->reg[r]=d;if(r<=5)tone_inc(a,r>>1);else if(r==6)noise_inc(a);else if(r==11||r==12)env_inc(a);else if(r==13)env_shape(a,d&15);}
static void env_tick(zz_ay8910_t*a){if(a->env_holding)return;a->env_step+=a->env_dir;if(a->env_step>=0&&a->env_step<=15)return;if(!a->env_continue){a->env_step=0;a->env_holding=1;return;}if(a->env_hold){if(a->env_alt)a->env_dir=-a->env_dir;a->env_step=(a->env_dir>0)?15:0;a->env_holding=1;}else{if(a->env_alt)a->env_dir=-a->env_dir;a->env_step=(a->env_dir>0)?0:15;}}
void zz_ay8910_render(zz_ay8910_t*a,int16_t*out,uint32_t frames){uint32_t i;for(i=0;i<frames;i++){int32_t l=0,r=0;unsigned ch;uint32_t old=a->noise_phase;a->noise_phase+=a->noise_inc;if(a->noise_phase<old){uint32_t bit=((a->lfsr>>0)^(a->lfsr>>3))&1u;a->lfsr=(a->lfsr>>1)|(bit<<16);}old=a->env_phase;a->env_phase+=a->env_inc;if(a->env_phase<old)env_tick(a);for(ch=0;ch<3;ch++){int toneok,noiseok,amp,v;a->phase[ch]+=a->inc[ch];toneok=(a->reg[7]&(1u<<ch))?1:((a->phase[ch]&0x80000000u)!=0);noiseok=(a->reg[7]&(1u<<(ch+3)))?1:((a->lfsr&1u)!=0);amp=(a->reg[8+ch]&0x10)?a->env_step:(a->reg[8+ch]&15);if(amp<0)amp=0;if(amp>15)amp=15;v=(toneok&&noiseok)?ayvol[amp]:-ayvol[amp];/* AC-centred approximation, gentle ABC stereo */{uint8_t lb=(uint8_t)(1u<<(ch*2));uint8_t rb=(uint8_t)(2u<<(ch*2));if(a->stereo==0x3f){/* default A-left/B-centre/C-right */if(ch==0)l+=v;else if(ch==1){l+=v/2;r+=v/2;}else r+=v;}else{if(a->stereo&lb)l+=v;if(a->stereo&rb)r+=v;}}}if(l>32767)l=32767;if(l<-32768)l=-32768;if(r>32767)r=32767;if(r<-32768)r=-32768;out[i*2]=(int16_t)l;out[i*2+1]=(int16_t)r;}}
